fn solve(n: i8, s: Vec<char>) -> i8 {
    // (x, y) is our current position
    let mut x: i8 = 0;
    let mut y: i8 = 0;
    // last_region: None = we've never entered A or B yet
    // Some(true) = last was Region A (x > y)
    // Some(false) = last was Region B (y > x)
    let mut last_region: Option<bool> = None;
    let mut transitions: i8 = 0;

    for mv in s.into_iter().take(n as usize) {
        // apply the move
        match mv {
            'U' => y += 1,
            'R' => x += 1,
            _ => {} // input guarantees only 'U' or 'R', so this is just a fallback
        }

        // determine the current region after the move
        if x > y {
            // we're in Region A now
            let curr_region = true;
            if let Some(prev_region) = last_region {
                // if we have a previous region and it's different, it's a transition
                if prev_region != curr_region {
                    transitions += 1;
                }
            }
            // update last known region to A
            last_region = Some(curr_region);
        } else if y > x {
            // we're in Region B now
            let curr_region = false;
            if let Some(prev_region) = last_region {
                // if we have a previous region and it's different, it's a transition
                if prev_region != curr_region {
                    transitions += 1;
                }
            }
            // update last known region to B
            last_region = Some(curr_region);
        }
        // if x == y, we're on the border; do not change last_region or count transitions
    }

    transitions
}

