        // R, U, R, U, R, U ...
        // positions: (1,0)=A, (1,1)=border, (2,1)=A, (2,2)=border, ...
        // never goes into B, so no transitions
        let moves = vec!['R','U','R','U','R','U'];
        assert_eq!(solve(6, moves), 0);
